<h2>Audit a redirect mapping before launch</h2>
<p class="lead">Enter one redirect per line as source URL and destination URL separated by a tab, comma or ->.</p>
<div class="form-grid"><div class="field full"><label for="map">Redirect map</label><textarea id="map">https://example.com/old-a -> https://example.com/new-a
https://example.com/old-b -> https://example.com/old-a</textarea></div></div>
<div class="tool-actions"><button class="btn btn-primary" id="calc">Analyze Map</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div>
<div class="result-box"><div class="result-grid"><div class="metric"><span>Valid map rows</span><strong id="rows">—</strong></div><div class="metric"><span>Duplicate sources</span><strong id="duplicates">—</strong></div><div class="metric"><span>Chain links</span><strong id="chains">—</strong></div><div class="metric"><span>Self-redirects</span><strong id="self">—</strong></div><div class="metric"><span>Loops found</span><strong id="loops">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><div class="result-box"><strong>Issues</strong><pre id="issues" class="code-output">—</pre></div>
<script>
(()=>{
const $=id=>document.getElementById(id);
const num=id=>{const v=parseFloat($(id)?.value);return Number.isFinite(v)?v:0;};
const money=(v,c='')=>Number.isFinite(v)?c+v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const dec=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const pct=v=>Number.isFinite(v)?v.toFixed(2)+'%':'—';
const note=(m,bad=false)=>{const el=$('note');if(el){el.textContent=m||'';el.className='helper'+(bad?' danger':'');}};
function parse(line){let p;if(line.includes('->'))p=line.split('->');else if(line.includes('\t'))p=line.split('\t');else p=line.split(',');if(p.length<2)return null;const a=p[0].trim(),b=p.slice(1).join(',').trim();try{return [new URL(a).href,new URL(b).href];}catch(e){return null;}}function go(){const lines=$('map').value.split(/\r?\n/).filter(x=>x.trim()),pairs=lines.map(parse).filter(Boolean),m=new Map(),dups=[],self=[];for(const [a,b] of pairs){if(m.has(a))dups.push(a);else m.set(a,b);if(a===b)self.push(a);}const chains=[];for(const [a,b] of m)if(m.has(b)&&b!==a)chains.push(a+' -> '+b+' -> '+m.get(b));const loops=new Set();for(const start of m.keys()){let cur=start,seen=[];while(m.has(cur)){if(seen.includes(cur)){const cyc=seen.slice(seen.indexOf(cur)).concat(cur);loops.add(cyc.join(' -> '));break;}seen.push(cur);cur=m.get(cur);if(seen.length>m.size+1)break;}}$('rows').textContent=pairs.length;$('duplicates').textContent=dups.length;$('chains').textContent=chains.length;$('self').textContent=self.length;$('loops').textContent=loops.size;const out=[];if(lines.length!==pairs.length)out.push(`${lines.length-pairs.length} line(s) could not be parsed as absolute source/destination URLs.`);if(dups.length)out.push('Duplicate sources:\n'+[...new Set(dups)].join('\n'));if(self.length)out.push('Self-redirects:\n'+self.join('\n'));if(chains.length)out.push('Redirect chains:\n'+chains.join('\n'));if(loops.size)out.push('Redirect loops:\n'+[...loops].join('\n'));$('issues').textContent=out.length?out.join('\n\n'):'No duplicate sources, self-redirects, chains or loops detected in the parsed map.';note(out.length?'Review the listed redirect-map issues before deployment.':'The parsed redirect map passed these structural checks.',out.length>0);} $('map').addEventListener('input',go);
if($('calc')) $('calc').addEventListener('click',go);
if($('reset')) $('reset').addEventListener('click',()=>{document.querySelectorAll('.tool-panel input,.tool-panel textarea,.tool-panel select').forEach(el=>{if(el.tagName==='SELECT') el.selectedIndex=0; else el.value=el.defaultValue;});go();});
document.querySelectorAll('.tool-panel input,.tool-panel select').forEach(el=>el.addEventListener('input',go));
go();
})();
</script>
